INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (2, "お！\nあそこに困ってそうな人発見！", 0, 1001, 1, 1, 0, "ねぇねぇ、騎士クン\n手伝ってあげようよ～", "春咲 ひより", 0, 1, "ヒヨリでっす♪\n元気いっぱいがんばるよ♪", 0, 1.4, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (2, "大切な人を\n守れるようになりたい…って", 0, 1002, 1, 1, 0, "わ、わたし、\nなに言ってるんだろ\nあはは…", "草野 優衣", 0, 1, "みんなみたいに\nわたしも強くならなきゃ", 0, 1.4, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (2, "キミに必要な集中力と感性が", 0, 1003, 1, 1, 0, "少しは磨かれると思いますよ。", "士条 怜", 0, 1, "フェンシングを始めてみては？", 0, 1.4, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (2, "今日はなにして遊ぶ？", 0, 1004, 1, 1, 0, "みそぎはねぇ、\nかくれんぼやりたい！", "穂高 みそぎ", 0, 1, "ねぇ、にいちゃん！", 0, 1.5, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (2, "ねぇ…", 0, 1006, 1, 1, 0, "私といっしょに…\nいかない？", "風宮 あかり", 0, 1, "風宮あかりです", 0, 1.4, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (2, "プリンたべたいのー", 0, 1007, 1, 1, 0, "食べ物の恨みは怖いのー", "出雲 宮子", 0, 1, "出雲宮子なのー", 0, 1.5, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (2, "キミもボクの美貌に\n吸い寄せられたんだね。", 0, 1008, 1, 1, 0, "いいよ。\n見られることは運命さ…", "虹村 雪", 0, 1, "ボクは虹村雪。", 0, 1.4, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (2, "我が真名は\nアンネローゼ・フォン・シュテッヒパルム！", 0, 1009, 1, 1, 0, "人呼んで「疾風の冥姫」!!", "柊杏奈", 0, 1, "フッ…聞いて後悔するがいい！", 0, 1.4, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (2, "うさぎさん、\n運命の王子はんに巡りあわせてくれて", 0, 1010, 1, 1, 0, "ほんまおおきにやわ～♪", "姫宮 真歩", 0, 1, "マホマホ王国のプリンセス、\nまほ姫どす", 0, 1.5, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (2, "生き別れたお兄ちゃんを探して\n三千世界！", 0, 1011, 1, 1, 0, "ここで会ったが\n100年目～！", "衣之咲 璃乃", 0, 1, "衣之咲璃乃です！", 0, 1.4, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (2, "ち、超能力って…\n何のことかな～？", 0, 1012, 1, 1, 0, "…って、お願い！\n誰にも言わないでおいて～！", "柏崎 初音", 0, 1, "私はハツネ、\n結構強いんだよ。\nきらーん☆", 0, 1.4, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (2, "一応カリスマ読モJKやってまっす！", 0, 1016, 1, 1, 0, "ヒデサイまぢ\nGF（グッドフィーリング）～♪", "美波 鈴奈", 0, 1, "ちょす！\n美波鈴奈だよ～♪", 0, 1.4, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (2, "東京は遊園地みたいなところさー", 0, 1017, 1, 1, 0, "でも、沖縄もとってもいいとこさー", "喜屋武 香織", 0, 1, "はいたーい。\n喜屋武香織さー。", 0, 1.4, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (2, "先生って呼ばれるのは\nくすぐったいから", 0, 1018, 1, 1, 0, "イオちゃんって呼んでね。", "支倉 伊緒", 0, 1, "支倉伊緒です。", 0, 1.4, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (2, "あ！/\お兄ちゃ～ん\nまってよ～", 0, 1020, 1, 1, 0, "ミミをおいてかないでぇ～", "茜 ミミ", 0, 1, "ふえ…？\nミミ、むずかしいこと\nよくわかんない…", 0, 1.5, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (2, "あの……\nふぇ……", 0, 1021, 1, 1, 0, "ふぇぇぇぇぇん……", "栗林 くるみ", 0, 1, "あ…あの…えっと…\n栗…林…くるみ…です……", 0, 1.5, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (2, "こんな私に貴重な時間を\n割いていただき、", 0, 1022, 1, 1, 0, "なんてありがとうございます！", "風宮 より", 0, 1, "風宮よりです。\nあああああ！", 0, 1.4, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (2, "おにいちゃんどこいくの？\nえ？", 0, 1023, 1, 1, 0, "私こっち行きたいー\nね、早く早くー", "北条 綾音", 0, 1, "私、アヤネ！\nぷうきちと一緒についてってあげるね！", 0, 1.5, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (2, "ふ、不束者ですが\nどうぞ末永く…って、", 0, 1025, 1, 1, 0, "これて何か違う…\nあああすみません！", "天野 すずめ", 0, 1, "わっ…わっ…私、\n天野すずめといいます！", 0, 1.4, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (2, "あなたは…運命の……\n伴侶……", 0, 1027, 1, 1, 0, "離しませんわ………\n絶対に…!!", "倉石 恵理子", 0, 1, "……クスクス…私は\n…倉石恵理子……", 0, 1.4, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (2, "その無駄を省くことができれば、\nもっと余裕のある暮らしができるっ！", 0, 1028, 1, 1, 0, "…そうでしょ？？", "佐々木 咲恋", 0, 1, "佐々木咲恋よ。\nねえ、世の中に無駄なことが\n多すぎると思わない？", 0, 1.4, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (2, "ぇっと…\nキミ、私のこと知らないの?!", 0, 1029, 1, 1, 0, "あはは、\n私もまだまだだなぁ～", "桜井 望", 0, 1, "桜井望だよ！\nよろしくねっ", 0, 1.4, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (2, "初めまして、\n私はニノン・ジュベール申すデス！", 0, 1030, 1, 1, 0, "ショーグン、\nワタシと一緒に天下統一デース！", "ニノン・ジュベール", 0, 1, "デケデケデンっ！", 0, 1.4, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (2, "でもって私の隣にいるのが……\nえ、見えない？", 0, 1031, 1, 1, 0, "おかしいですね……", "上喜 しのぶ", 0, 1, "上喜しのぶです。\n手元のドクロが父です。", 0, 1.4, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (2, "けんども\nそれには足りないモンが…", 0, 1033, 1, 1, 0, "そう、\nオラのボケに突っ込める相方が…！", "野戸まひる", 0, 1, "目指すはビッグな\nお笑い芸人だっぺ！", 0, 1.5, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (2, "ちょっと緊張しちゃって…", 0, 1034, 1, 1, 0, "ちょ\nちょっと一杯飲んできます…！", "綾瀬 ゆかり", 0, 1, "あの…私…綾瀬ゆかりです…\nあの…ごめんなさい！", 0, 1.4, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (2, "知らない人とは話しちゃいけないので", 0, 1036, 1, 1, 0, "これ以上お話しすることは…\nないです！", "氷川 鏡華", 0, 1, "氷川鏡華…です", 0, 1.5, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (2, "……あ、アラーム。", 0, 1038, 1, 1, 0, "私体が弱いから、\n30分に一度休憩しないと\nいけないんです。", "柏崎 栞", 0, 1, "柏崎…栞です。", 0, 1.4, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (2, "私、一人も友達がいなくて……", 0, 1040, 1, 1, 0, "野に咲く花が、\n唯一の話相手です。", "双葉 碧", 0, 1, "ふ、双葉碧です。", 0, 1.4, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (2, "私の歌声で、\n皆さんが幸せになってくれたらいいなって…", 0, 1042, 1, 1, 0, "そう思っています。", "三角 千歌", 0, 1, "三角千歌です。", 0, 1.4, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (2, "あぁ？\nお前のそいつの仲間か？", 0, 1043, 1, 1, 0, "う、疑ってすまなかったな…", "安芸 真琴", 0, 1, "安芸真琴だ。", 0, 1.4, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (2, "生けとし生ける全ての者よ！", 0, 1044, 1, 1, 0, "わらわの偉大な力に\nひれ伏すがいい！\nはっはっは！", "イリヤ・オーンスタイン", 0, 1, "わらわこそは夜を総べる者！", 0, 1.4, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (2, "ぐふふふふ……はっ！", 0, 1045, 1, 1, 0, "ｌク、クウカに何かご用ですか!?", "遠見 空花", 0, 1, "そこで騎士は妖精を乱暴に……", 0, 1.4, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (2, "自由気ままで♪\n寝て遊んで、食べてケンカして…", 0, 1046, 1, 1, 0, "う～ん…\n猫ってホントに最高にゃ～♪", "宮坂たまき", 0, 1, "宮坂たまきにゃ♪\n猫はいいにゃよ？", 0, 1.4, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (2, "それでは早速クエストに…", 0, 1048, 1, 1, 0, "…と思ったら\nバイトの時間だ！\nまたあとでね！", "大神 美冬", 0, 1, "大神美冬よ！", 0, 1.4, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (2, "クエストもバトルも\n掃除も洗濯も", 0, 1049, 1, 1, 0, "お姉ちゃんがぜ～んぶ\nやってあげるからね！", "星野静流", 0, 1, "星野静流だよ！", 0, 1.4, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (2, "見ての通りの\nセクシー美少女で", 0, 1050, 1, 1, 0, "学校では誰もが憧れる\nアイドル的な存在ってやつよ♪", "玉泉美咲", 0, 1, "アタシは玉泉美咲。", 0, 1.5, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (2, "？？？？", 0, 1052, 1, 1, 0, "？？？？", "リマ", 0, 1, "？？？", 0, 1.4, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (2, "菓子でつろうなどと\n稚拙な策を……", 0, 1053, 1, 1, 0, "そ、そこまでいうなら\nもらってやる", "モニカ・ヴァイスヴィント", 0, 1, "モニカ・ヴァイスヴィントだ。", 0, 1.5, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (2, "菓子でつろうなどと\n稚拙な策を……", 0, 1058, 1, 1, 0, "そ、そこまでいうなら\nもらってやる", "ペコリーヌ", 0, 1, "モニカ・ヴァイスヴィントだ。", 0, 1.5, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (2, "菓子でつろうなどと\n稚拙な策を……", 0, 1059, 1, 1, 0, "そ、そこまでいうなら\nもらってやる", "コッコロ", 0, 1, "モニカ・ヴァイスヴィントだ。", 0, 1.5, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (2, "菓子でつろうなどと\n稚拙な策を……", 0, 1060, 1, 1, 0, "そ、そこまでいうなら\nもらってやる", "キャル", 0, 1, "モニカ・ヴァイスヴィントだ。", 0, 1.5, 0);
